<?php require '_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');if($title&&$body){$s=$pdo->prepare("INSERT INTO announcements(title,body,created_by) VALUES(?,?,?)");$s->execute([$title,$body,(int)$_SESSION['admin_id']]);flash('success','Announcement published.');}else flash('danger','Both fields are required.');go('announcements.php');}$rows=$pdo->query("SELECT * FROM announcements ORDER BY created_at DESC")->fetchAll();$pageTitle='Announcements';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">ADMIN / COMMUNITY</div><h1>ANNOUNCE THE <span>PLAY.</span></h1></section><?php require 'nav.php';?><div class="form-layout section"><section class="box"><div class="eyebrow">NEW UPDATE</div><h2>Publish announcement</h2><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Headline<input name="title" required></label><label>Message<textarea name="body" rows="5" required></textarea></label><button class="btn btn-hot">Publish ↗</button></form></section><section class="box"><div class="eyebrow">PUBLISHED UPDATES</div><h2>Announcement feed</h2><?php foreach($rows as $r):?><div class="list-row"><div><small><?=e(date('d M Y',strtotime($r['created_at'])))?></small><b><?=e($r['title'])?></b><p><?=nl2br(e($r['body']))?></p></div></div><?php endforeach;?></section></div><?php require '../includes/footer.php';?>
